replacements.text:
SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    shift_cursor[0] = shift_cursor[-1];
    --shift_cursor;
    shift_cursor[1].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    *shift_cursor = *(shift_cursor - 1);
    --shift_cursor;
    shift_cursor[1].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    shift_cursor[0] = shift_cursor[-1];
    --shift_cursor;
    --shift_rank;
    shift_cursor[1].route_or_rank_index = shift_rank + 1;
} while (shift_rank > rank);

SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    SubSolution* destination = shift_cursor;
    destination[0] = shift_cursor[-1];
    --shift_cursor;
    shift_cursor[1].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

SubSolution* shift_cursor = &bank->survival_records[shift_rank];
do {
    SubSolution* source = shift_cursor - 1;
    shift_cursor[0] = source[0];
    shift_cursor = source;
    shift_cursor[1].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

do {
    bank->survival_records[shift_rank] =
        bank->survival_records[shift_rank - 1];
    bank->survival_records[shift_rank].route_or_rank_index = shift_rank;
    --shift_rank;
} while (shift_rank > rank);

do {
    --shift_rank;
    bank->survival_records[shift_rank + 1] =
        bank->survival_records[shift_rank];
    bank->survival_records[shift_rank + 1].route_or_rank_index =
        shift_rank + 1;
} while (shift_rank > rank);
